// The scorecard: does Ward catch abuse that an English-first safety model misses?
// Each system sees the same balanced sample from three public datasets and says, per message,
// "abusive or not". Results go to eval/results/scorecard.{json,md}.
//
//   pnpm eval                          200 per language (the published numbers)
//   pnpm eval -- 40                    a quick run
//   pnpm eval -- --only="Ward Lite"    rerun named systems; keep the rest from the last run
//
// Ward Lite's predictions come from train/score.py (it runs the exported ONNX model), written to
// results/ward-lite.preds.json; run that first.

import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { GemmaJudge, PackMatcher, ShieldGemmaJudge, type Chat } from "../packages/engine/src/index.ts";
import { loadSets, type Item } from "./data.ts";

const N = Number(process.argv.find((a) => /^\d+$/.test(a)) ?? 200);
// --only=a,b: rerun just these systems and keep the others' results from the last run.
// --packs-only is kept as shorthand for --only="Slang packs".
const onlyArg = process.argv.find((a) => a.startsWith("--only="))?.slice(7) ?? (process.argv.includes("--packs-only") ? "Slang packs" : null);
const ONLY = onlyArg ? new Set(onlyArg.split(",").map((s) => s.trim())) : null;
const sets = await loadSets(N);
const packs = new PackMatcher();
const shield = new ShieldGemmaJudge();

type System = { name: string; about: string; run: (items: Item[]) => Promise<boolean[]> };

function asChat(items: Item[]): Chat {
  return {
    source: "paste",
    events: [],
    participants: items.map((_, i) => `user${i}`),
    messages: items.map((it, i) => ({ id: i, at: null, sender: `user${i}`, text: it.text, media: false })),
  };
}

async function gemma(model: string, items: Item[], batch = 20) {
  const j = new GemmaJudge({ model, batch, context: 0 });
  const got = await j.judge(asChat(items), {
    self: null,
    onProgress: (d, t) => process.stderr.write(`\r  ${model} ${d}/${t}   `),
  });
  process.stderr.write("\n");
  return items.map((_, i) => got.get(i)?.hostile ?? false);
}

const systems: System[] = [
  { name: "Slang packs", about: "Ward's word lists alone: no model, works on any phone", run: async (items) => items.map((i) => packs.match(i.text).some((h) => h.severity >= 1)) },
  {
    name: "ShieldGemma 2B",
    about: "Google's open safety classifier, harassment policy",
    run: async (items) => {
      const out: boolean[] = [];
      for (const [k, i] of items.entries()) {
        out.push(await shield.violates(i.text));
        process.stderr.write(`\r  shieldgemma ${k + 1}/${items.length}   `);
      }
      process.stderr.write("\n");
      return out;
    },
  },
  { name: "Gemma 4 E4B", about: "Ward's judge prompt, one message at a time, no chat context (the computer tier)", run: (items) => gemma("gemma4:e4b", items) },
  { name: "Gemma 4 E2B", about: "The same prompt on the phone-sized Gemma 4, 5 messages per request (it loses track of longer lists); scored through Ollama, on a phone it runs through LiteRT-LM", run: (items) => gemma("gemma4:e2b", items, 5) },
  {
    name: "Ward Lite",
    about: "The small classifier distilled for any phone (train/), int8 ONNX, flagged when hurtful or dangerous >= 0.5",
    run: async (items) => litePreds(items),
  },
  {
    name: "Phone: packs + Ward Lite",
    about: "What a phone without a big model does: a message counts if the word lists or Ward Lite flag it (Ward Lite can only add)",
    run: async (items) => {
      const lite = litePreds(items);
      return items.map((it, i) => lite[i]! || packs.match(it.text).some((h) => h.severity >= 1));
    },
  },
];

let liteFile: Record<string, Record<string, boolean>> | null = null;
function litePreds(items: Item[]): boolean[] {
  liteFile ??= JSON.parse(readFileSync(new URL("./results/ward-lite.preds.json", import.meta.url), "utf8"));
  return items.map((it) => {
    const p = liteFile![it.set]?.[it.text];
    if (p === undefined) throw new Error("ward-lite.preds.json is from a different sample: rerun train/score.py");
    return p;
  });
}

function score(pred: boolean[], items: Item[]) {
  let tp = 0, fp = 0, fn = 0, tn = 0;
  pred.forEach((p, i) => {
    const b = items[i]!.bad;
    if (p && b) tp++;
    else if (p) fp++;
    else if (b) fn++;
    else tn++;
  });
  const precision = tp / Math.max(1, tp + fp);
  const recall = tp / Math.max(1, tp + fn);
  const f1 = (2 * precision * recall) / Math.max(1e-9, precision + recall);
  return { tp, fp, fn, tn, precision, recall, f1, accuracy: (tp + tn) / items.length };
}

const results: Record<string, Record<string, ReturnType<typeof score> & { seconds: number }>> = {};
const raw: Record<string, Record<string, boolean[]>> = {};
const prev = ONLY ? JSON.parse(readFileSync(new URL("./results/scorecard.raw.json", import.meta.url), "utf8")) : null;
for (const [set, items] of Object.entries(sets)) {
  results[set] = {};
  raw[set] = {};
  for (const sys of systems) {
    if (ONLY && !ONLY.has(sys.name)) {
      const pred = prev.raw[set]?.[sys.name] as boolean[] | undefined;
      if (!pred) continue;
      raw[set]![sys.name] = pred;
      results[set]![sys.name] = { ...score(pred, items), seconds: 0 };
      continue;
    }
    console.error(`${set} / ${sys.name}`);
    const t = Date.now();
    const pred = await sys.run(items);
    raw[set]![sys.name] = pred;
    results[set]![sys.name] = { ...score(pred, items), seconds: (Date.now() - t) / 1000 };
  }
}

const pct = (x: number) => `${Math.round(x * 100)}%`;
const md = [
  `# Ward scorecard`,
  ``,
  `${N} messages per language, half abusive and half not by each dataset's own labels, same sample for every system (seed 26).`,
  `Run on ${new Date().toISOString().slice(0, 10)}, Apple M-series laptop, Ollama, nothing sent off the machine.`,
  ``,
  `Recall is the share of abusive messages caught. Precision is the share of flags that were right.`,
  ``,
  ...Object.entries(results).flatMap(([set, r]) => [
    `## ${set}`,
    ``,
    `| System | Caught (recall) | Right when it flags (precision) | F1 | Accuracy |`,
    `| --- | --- | --- | --- | --- |`,
    ...Object.entries(r).map(([s, v]) => `| ${s} | ${pct(v.recall)} | ${pct(v.precision)} | ${v.f1.toFixed(2)} | ${pct(v.accuracy)} |`),
    ``,
  ]),
  `## Systems`,
  ``,
  ...systems.map((s) => `- **${s.name}**: ${s.about}`),
  ``,
  `## Datasets`,
  ``,
  `- Roman Urdu: [community-datasets/roman_urdu_hate_speech](https://huggingface.co/datasets/community-datasets/roman_urdu_hate_speech), Coarse_Grained validation split (Abusive/Offensive vs Normal).`,
  `- Bangla: [yamin401533/bangla-cyberbullying-blindspot](https://huggingface.co/datasets/yamin401533/bangla-cyberbullying-blindspot), test split, labels Personal and Gender abusive vs Non-abusive (political and geopolitical rants left out, as they aren't aimed at a person).`,
  `- English: [surrey-nlp/Cyberbullying-Detection-CB1](https://huggingface.co/datasets/surrey-nlp/Cyberbullying-Detection-CB1), test split, classes not_cyberbullying vs gender and other_cyberbullying.`,
  ``,
  `These are public social-media datasets with noisy labels, not children's chats. They test language coverage; the pattern engine (pile-ons, repeated targeting, ghost accounts) is tested on the chats in packages/engine/fixtures.`,
].join("\n");

mkdirSync(new URL("./results/", import.meta.url), { recursive: true });
writeFileSync(new URL("./results/scorecard.json", import.meta.url), JSON.stringify({ n: N, results }, null, 2));
writeFileSync(new URL("./results/scorecard.raw.json", import.meta.url), JSON.stringify({ sets, raw }));
writeFileSync(new URL("./results/scorecard.md", import.meta.url), md + "\n");
console.log(md);
// Downloads and caches the public eval sets from the Hugging Face datasets server, then draws a
// fixed, balanced sample from each so every run scores the same messages.

import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";

export interface Item {
  text: string;
  /** true = abusive / bullying, per the dataset's own labels. */
  bad: boolean;
  set: string;
}

const DIR = new URL("./data/", import.meta.url);

async function rows(dataset: string, config: string, split: string): Promise<Record<string, unknown>[]> {
  const file = new URL(`${dataset.replace("/", "__")}__${config}__${split}.json`, DIR);
  if (existsSync(file)) return JSON.parse(readFileSync(file, "utf8"));
  mkdirSync(DIR, { recursive: true });
  const out: Record<string, unknown>[] = [];
  for (let offset = 0; ; offset += 100) {
    const url = `https://datasets-server.huggingface.co/rows?dataset=${dataset}&config=${config}&split=${split}&offset=${offset}&length=100`;
    let j: { rows?: { row: Record<string, unknown> }[]; num_rows_total?: number } = {};
    for (let attempt = 0; attempt < 4; attempt++) {
      const r = await fetch(url);
      if (r.ok) {
        j = await r.json();
        break;
      }
      await new Promise((res) => setTimeout(res, 1500 * (attempt + 1)));
    }
    out.push(...(j.rows ?? []).map((r) => r.row));
    if (!j.rows?.length || out.length >= (j.num_rows_total ?? 0)) break;
  }
  writeFileSync(file, JSON.stringify(out));
  return out;
}

/** Deterministic shuffle (mulberry32) so the sample never changes between runs. */
function shuffle<T>(xs: T[], seed = 26): T[] {
  let a = seed;
  const rand = () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
  const out = [...xs];
  for (let i = out.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [out[i], out[j]] = [out[j]!, out[i]!];
  }
  return out;
}

function balanced(items: Item[], n: number): Item[] {
  const s = shuffle(items.filter((i) => i.text.trim().length > 3));
  return shuffle([...s.filter((i) => i.bad).slice(0, n / 2), ...s.filter((i) => !i.bad).slice(0, n / 2)]);
}

export async function loadSets(n: number): Promise<Record<string, Item[]>> {
  const ru = await rows("community-datasets/roman_urdu_hate_speech", "Coarse_Grained", "validation");
  const bn = await rows("yamin401533/bangla-cyberbullying-blindspot", "default", "test");
  const en = await rows("surrey-nlp/Cyberbullying-Detection-CB1", "default", "test");
  return {
    "Roman Urdu": balanced(
      ru.filter((r) => r.label != null).map((r) => ({ text: String(r.tweet), bad: r.label === 0, set: "Roman Urdu" })),
      n,
    ),
    Bangla: balanced(
      bn
        // Political and geopolitical rants aren't aimed at a child; keep abuse aimed at a person.
        .filter((r) => ["Non-abusive", "Personal", "Gender abusive"].includes(String(r.label)))
        .map((r) => ({ text: String(r.text), bad: r.label !== "Non-abusive", set: "Bangla" })),
      n,
    ),
    English: balanced(
      en
        // The "age/religion/ethnicity" classes are mostly tweets about bullying, not aimed at a person;
        // keep the targeted classes so the set asks the same question Ward does.
        .filter((r) => ["not_cyberbullying", "gender", "other_cyberbullying"].includes(String(r.cyberbullying_type)))
        .map((r) => ({ text: String(r.tweet_text), bad: r.cyberbullying_type !== "not_cyberbullying", set: "English" })),
      n,
    ),
  };
}
# Ward scorecard

200 messages per language, half abusive and half not by each dataset's own labels, same sample for every system (seed 26).
Run on 2026-10-31, Apple M-series laptop, Ollama, nothing sent off the machine.

Recall is the share of abusive messages caught. Precision is the share of flags that were right.

## Roman Urdu

| System | Caught (recall) | Right when it flags (precision) | F1 | Accuracy |
| --- | --- | --- | --- | --- |
| Slang packs | 59% | 94% | 0.72 | 78% |
| ShieldGemma 2B | 14% | 70% | 0.23 | 54% |
| Gemma 4 E4B | 86% | 86% | 0.86 | 86% |
| Gemma 4 E2B | 33% | 75% | 0.46 | 61% |
| Ward Lite | 79% | 90% | 0.84 | 85% |
| Phone: packs + Ward Lite | 83% | 86% | 0.85 | 85% |

## Bangla

| System | Caught (recall) | Right when it flags (precision) | F1 | Accuracy |
| --- | --- | --- | --- | --- |
| Slang packs | 10% | 83% | 0.18 | 54% |
| ShieldGemma 2B | 14% | 93% | 0.24 | 56% |
| Gemma 4 E4B | 65% | 78% | 0.71 | 74% |
| Gemma 4 E2B | 34% | 71% | 0.46 | 60% |
| Ward Lite | 40% | 78% | 0.53 | 65% |
| Phone: packs + Ward Lite | 46% | 79% | 0.58 | 67% |

## English

| System | Caught (recall) | Right when it flags (precision) | F1 | Accuracy |
| --- | --- | --- | --- | --- |
| Slang packs | 10% | 91% | 0.18 | 55% |
| ShieldGemma 2B | 19% | 73% | 0.30 | 56% |
| Gemma 4 E4B | 36% | 72% | 0.48 | 61% |
| Gemma 4 E2B | 33% | 69% | 0.45 | 59% |
| Ward Lite | 84% | 67% | 0.74 | 71% |
| Phone: packs + Ward Lite | 85% | 67% | 0.75 | 72% |

## Systems

- **Slang packs**: Ward's word lists alone: no model, works on any phone
- **ShieldGemma 2B**: Google's open safety classifier, harassment policy
- **Gemma 4 E4B**: Ward's judge prompt, one message at a time, no chat context (the computer tier)
- **Gemma 4 E2B**: The same prompt on the phone-sized Gemma 4, 5 messages per request (it loses track of longer lists); scored through Ollama, on a phone it runs through LiteRT-LM
- **Ward Lite**: The small classifier distilled for any phone (train/), int8 ONNX, flagged when hurtful or dangerous >= 0.5
- **Phone: packs + Ward Lite**: What a phone without a big model does: a message counts if the word lists or Ward Lite flag it (Ward Lite can only add)

## Datasets

- Roman Urdu: [community-datasets/roman_urdu_hate_speech](https://huggingface.co/datasets/community-datasets/roman_urdu_hate_speech), Coarse_Grained validation split (Abusive/Offensive vs Normal).
- Bangla: [yamin401533/bangla-cyberbullying-blindspot](https://huggingface.co/datasets/yamin401533/bangla-cyberbullying-blindspot), test split, labels Personal and Gender abusive vs Non-abusive (political and geopolitical rants left out, as they aren't aimed at a person).
- English: [surrey-nlp/Cyberbullying-Detection-CB1](https://huggingface.co/datasets/surrey-nlp/Cyberbullying-Detection-CB1), test split, classes not_cyberbullying vs gender and other_cyberbullying.

These are public social-media datasets with noisy labels, not children's chats. They test language coverage; the pattern engine (pile-ons, repeated targeting, ghost accounts) is tested on the chats in packages/engine/fixtures.

// The red-team run: scores Ward on the hand-written red-team set (eval/redteam/*.jsonl) the same
// way eval/run.ts scores the scorecard, per language and per trick, and writes
// eval/results/redteam.{json,md} and docs/REDTEAM.md. Report only: nothing here tunes the engine.
//
//   pnpm redteam:lite        Ward Lite's scores (train/.venv; rerun when the model or the set changes)
//   pnpm redteam             word lists, Ward Lite, and the phone's combination
//   pnpm redteam -- --gemma  also Gemma 4 E4B through Ollama (kept for later runs while the set is unchanged)
//   pnpm redteam -- --packs-only   skip Ward Lite (no Python environment)

import { createHash } from "node:crypto";
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { GemmaJudge, PackMatcher, type Chat } from "../../packages/engine/src/index.ts";
import { CLASSES, CLASS_NAMES, LANGS, loadRedteam, type Lang, type RedClass, type RedItem } from "./set.ts";

const GEMMA = process.argv.includes("--gemma");
const PACKS_ONLY = process.argv.includes("--packs-only");

const items = loadRedteam();
const packs = new PackMatcher();

const RESULTS = new URL("../results/", import.meta.url);
const OUT_JSON = new URL("redteam.json", RESULTS);
const LITE_PREDS = new URL("redteam-lite.preds.json", RESULTS);
const LITE_DIR = new URL("../../apps/web/public/models/ward-lite/", import.meta.url);
const DOC = new URL("../../docs/REDTEAM.md", import.meta.url);

/** One system's call on one message. */
interface Pred {
  flag: boolean;
  /** Marked dangerous (severity 3, or Ward Lite's danger output). */
  danger: boolean;
  /** Why, in a few words, for the failure lists. */
  why: string;
  /** The model skipped this message; counted as not flagged, as the app and the scorecard do. */
  noAnswer?: boolean;
}
interface System {
  name: string;
  about: string;
  run: () => Promise<Pred[]>;
}

// ---- Word lists: exactly what eval/run.ts counts (any hit of severity 1 or more).
function packPreds(): Pred[] {
  return items.map((it) => {
    const hits = packs.match(it.text).filter((h) => h.severity >= 1);
    return {
      flag: hits.length > 0,
      danger: hits.some((h) => h.severity >= 3),
      why: hits.length ? `word list: ${hits.map((h) => `"${h.term}" (${h.category}, ${h.severity})`).join(", ")}` : "no word-list hit",
    };
  });
}

// ---- Ward Lite: raw scores from score-lite.py, thresholds applied the way apps/web/src/lib/lite.ts does.
interface LiteMeta {
  threshold: number;
  thresholds?: Partial<Record<"bengali" | "devanagari" | "latin", number>>;
  danger_threshold?: number;
}
function script(text: string): "bengali" | "devanagari" | "latin" {
  if (/[ঀ-৿]/.test(text)) return "bengali";
  if (/[ऀ-ॿ]/.test(text)) return "devanagari";
  return "latin";
}
let liteCache: Pred[] | null = null;
function litePreds(): Pred[] {
  if (liteCache) return liteCache;
  const again = "run `pnpm redteam:lite` first (or pass --packs-only)";
  if (!existsSync(LITE_PREDS)) throw new Error(`No Ward Lite scores for the red-team set: ${again}.`);
  const file = JSON.parse(readFileSync(LITE_PREDS, "utf8")) as { model_sha256: string; probs: Record<string, [number, number]> };
  const sha = createHash("sha256").update(readFileSync(new URL("onnx/model_quantized.onnx", LITE_DIR))).digest("hex");
  if (file.model_sha256 !== sha) throw new Error(`Ward Lite's scores are from a different model: ${again}.`);
  const meta = JSON.parse(readFileSync(new URL("ward-lite.json", LITE_DIR), "utf8")) as LiteMeta;
  liteCache = items.map((it) => {
    const p = file.probs[it.text];
    if (!p) throw new Error(`Ward Lite's scores are from an older red-team set (no score for ${it.id}): ${again}.`);
    const [hurt, danger] = p;
    const t = meta.thresholds?.[script(it.text)] ?? meta.threshold;
    const dt = meta.danger_threshold ?? meta.threshold;
    const isDanger = danger >= dt;
    return { flag: hurt >= t || isDanger, danger: isDanger, why: `Ward Lite: hurtful ${hurt.toFixed(2)} (flags at ${t}), danger ${danger.toFixed(2)} (at ${dt})` };
  });
  return liteCache;
}

// ---- Gemma 4 E4B, the computer tier: the same call as eval/run.ts (no chat context).
async function gemmaPreds(): Promise<Pred[]> {
  const chat: Chat = {
    source: "paste",
    events: [],
    participants: items.map((_, i) => `user${i}`),
    messages: items.map((it, i) => ({ id: i, at: null, sender: `user${i}`, text: it.text, media: false })),
  };
  const got = await new GemmaJudge({ model: "gemma4:e4b", batch: 20, context: 0 }).judge(chat, {
    self: null,
    onProgress: (d, t) => process.stderr.write(`\r  gemma4:e4b ${d}/${t}   `),
  });
  process.stderr.write("\n");
  return items.map((_, i) => {
    const j = got.get(i);
    if (!j) return { flag: false, danger: false, why: "Gemma skipped this message (no verdict)", noAnswer: true };
    return { flag: j.hostile, danger: j.severity >= 3, why: `Gemma: ${j.why ?? (j.hostile ? "hostile" : "fine")}` };
  });
}

const GEMMA_NAME = "Gemma 4 E4B";
const prev = existsSync(OUT_JSON) ? (JSON.parse(readFileSync(OUT_JSON, "utf8")) as { items?: { text: string; preds: Record<string, Pred> }[] }) : null;
function cachedGemma(): Pred[] | null {
  const byText = new Map((prev?.items ?? []).map((i) => [i.text, i.preds[GEMMA_NAME]]));
  const out = items.map((it) => byText.get(it.text));
  return out.every((p) => p) ? (out as Pred[]) : null;
}

const systems: System[] = [
  { name: "Slang packs", about: "Ward's word lists alone: no model, works on any phone", run: async () => packPreds() },
];
if (!PACKS_ONLY) {
  systems.push(
    { name: "Ward Lite", about: "The small classifier (train/), int8 ONNX, flagged when hurtful or dangerous passes its threshold, as in the app", run: async () => litePreds() },
    {
      name: "Phone: packs + Ward Lite",
      about: "What a phone without a big model does: flagged if the word lists or Ward Lite flag it (Ward Lite can only add)",
      run: async () => {
        const p = packPreds();
        const l = litePreds();
        return items.map((_, i) => ({
          flag: p[i]!.flag || l[i]!.flag,
          danger: p[i]!.danger || l[i]!.danger,
          why: [p[i]!.flag || !l[i]!.flag ? p[i]!.why : "", l[i]!.flag || !p[i]!.flag ? l[i]!.why : ""].filter(Boolean).join("; "),
        }));
      },
    },
  );
}
const cached = GEMMA ? null : cachedGemma();
if (GEMMA || cached) {
  systems.push({
    name: GEMMA_NAME,
    about: `Ward's judge prompt on a computer, through Ollama, no chat context${GEMMA ? "" : " (kept from an earlier run with --gemma on this same set)"}`,
    run: async () => cached ?? gemmaPreds(),
  });
}

const preds: Record<string, Pred[]> = {};
for (const s of systems) {
  console.error(s.name);
  preds[s.name] = await s.run();
}

