  ...(PACKS_ONLY ? ["Ward Lite (run without --packs-only after `pnpm redteam:lite`)"] : []),
  ...(names.includes(GEMMA_NAME) ? [] : ["Gemma 4 E4B (pass --gemma with Ollama running)"]),
