  ...head(["", ...langs.map((l) => LANGS[l])]),
  ...CLASSES.map((c) => row([c, ...langs.map((l) => {
    const t = byLangClass[l]![c]!;
    return `${t.hurtful ? `${t.caught}/${t.hurtful}` : "–"} · ${t.falseAlarms}/${t.harmless}`;
