  ...langs.map((l): [string, (s: string) => string] => [LANGS[l], (s) => frac(...f(byLang[s]![l]!))]),
  ["**All**", (s) => `**${fracCI(...f(byLang[s]!.all!))}**`],
];
const classRows = (f: (t: Tally) => string, only = CLASSES as readonly RedClass[]): [string, (s: string) => string][] =>
