];

/** "kisi ko mat batana", "don't tell anyone": how a threat or grooming ends, never an upstander. */
const TELL_NOBODY = /\b(kisi ko|kissi ko|don'?t tell (anyone|anybody|no ?one|nobody)|dont tell (anyone|anybody|no ?one|nobody))\b|কাউকে|কাউরে/;

/**
 * Wider than the frames above, and only ever used to hold back a nudge: "he sent me this: ur
 * ugly" or "usne mujhe kaha tu moti hai" may be a report even though Ward can't be sure enough to
 * hide who wrote it. Skipping a nudge lowers no alert and drops no check-in.
 */
const MAYBE: RegExp[] = [
  /\b(sent|sends|sending|asked|asks|asking|wants|wanted|called|calls|calling)\s+me\b/,
  /\b(posted|posting|shared|sharing|leaked|leaking|spread|spreading)\s+(my|our)\b/,
];

let words: PackMatcher | undefined;
const isAbuse = (s: string) => (words ??= new PackMatcher()).match(s).length > 0;

const clean = (text: string) => text.toLowerCase().replace(/[’‘`]/g, "'").replace(/\s+/g, " ").trim();
const sayItTo = (t: string) => SAY_IT_TO.some((re) => [...t.matchAll(re)].some((m) => isAbuse(m[2]!)));

export function frameOf(text: string): Frame | null {
  const t = clean(text);
  if (VETO.some((re) => re.test(t))) return null;
  if (REPORTING.some((re) => re.test(t))) return "reporting";
  if (TELL_NOBODY.test(t)) return null;
  if (UPSTANDING.some((re) => re.test(t)) || sayItTo(t)) return "upstanding";
  return null;
}

/** Could this be someone telling what happened, or standing up for someone? Enough to skip a nudge, nothing more. */
export function maybeFramed(text: string): boolean {
  const t = clean(text);
  return [...REPORTING, ...UPSTANDING, ...MAYBE].some((re) => re.test(t)) || sayItTo(t);
}

/**
 * Asking for help, or sounding hurt: "what do i do", "i can't stop thinking about it", "kya karun",
 * "ভয় লাগছে", crying. English, Roman Urdu / Hinglish, Urdu and Bangla.
 */
const HELP: RegExp[] = [
  /\b(what (do|should|can) i do|what to do|don'?t know what to do|dont know what to do|help me|i need help|need some help|can'?t stop thinking|cant stop thinking|i'?m (so |really )?(scared|afraid|upset|not ok|not okay)|im (so |really )?(scared|afraid|upset|not ok|not okay)|i feel (sick|awful|terrible|horrible|scared|alone|so bad)|i (cried|was crying|keep crying)|it (really )?hurts?|is (this|that) (normal|ok|okay)|should i tell)\b/,
  /\b(kya karu|kya karun|kya karoon|kya kru|ab kya karun|samajh nahi aa raha|samajh nahin aa raha|samjh nahi aa rha|madad|help karo|help kar do|dar lag|darr lag|dar lagta|dar gayi|dar gaya|ro rahi|ro raha|rona aa|bura lag|kisi ko bataun|kisko bataun)\b/,
  /کیا\s*کروں|مدد|ڈر\s*لگ|رو\s*رہ|برا\s*لگ/,
  /(কী|কি)\s*করব|ভয়\s*লাগ|সাহায্য|কান্না|কাঁদছি|খারাপ\s*লাগ|\b(ki korbo|bhoy lag|sahajjo)\b/,
  /😢|😭|💔|🥺|😞|😔|😟/u,
];

/**
 * Someone telling what was done to them and asking for help, or sounding hurt: "someone told me
 * to kys and i can't stop thinking about it", "usne mujhe kaha mar ja, kya karun". They may need
 * support; they aren't the bully. Needs both: a first-person recipient (frameOf's "reporting",
 * never a bare "someone said" or quotation marks) and help-seeking or distress in the same message.
 */
export function needsSupport(text: string): boolean {
  if (frameOf(text) !== "reporting") return false;
  const t = clean(text);
  return HELP.some((re) => re.test(t)) || selfDistress(text) !== null;
}

